@Composable private fun Step(n:String,t:String,s:String,c:Color){Row(Modifier.fillMaxWidth().padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(34.dp).background(c.copy(alpha=.18f),RoundedCornerShape(11.dp)),contentAlignment=Alignment.Center){Text(n,color=c,fontWeight=FontWeight.Black)};Spacer(Modifier.width(12.dp));Column{Text(t,fontWeight=FontWeight.SemiBold);Text(s,color=c,fontSize=12.sp)}}}
@Composable private fun Two(t1:String,v1:String,t2:String,v2:String){Row(Modifier.fillMaxWidth().padding(bottom=8.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf(t1 to v1,t2 to v2).forEach{(t,v)->Card(colors=CardDefaults.cardColors(containerColor=Panel),modifier=Modifier.weight(1f)){Column(Modifier.padding(12.dp)){Text(t,color=Muted,fontSize=10.sp);Text(v,fontWeight=FontWeight.Bold,fontSize=13.sp)}}}}}
@Composable private fun Pill(s:String){val c=when(s){"approved","activation_sent","active"->Mint;"rejected"->Danger;else->Warning};Surface(color=c.copy(alpha=.14f),shape=RoundedCornerShape(99.dp)){Text(s,color=c,fontSize=10.sp,modifier=Modifier.padding(horizontal=9.dp,vertical=5.dp))}}
private fun brl(v:Double)=NumberFormat.getCurrencyInstance(Locale("pt","BR")).format(v)
private fun pct(v:Double)=String.format(Locale.US,"%.2f",v).replace(".",",")
private fun maskCpf(c:String):String{val d=c.filter(Char::isDigit);return if(d.length==11)"***.${d.substring(3,6)}.${d.substring(6,9)}-**" else c}
private fun friendly(e:Exception):String{val r=e.message?:"Erro inesperado";return when{r.contains("application_already_exists",true)->"Já existe um cadastro em análise para este CPF.";r.contains("invalid_email",true)->"E-mail inválido.";r.contains("minimum_age_18",true)->"O cadastro exige idade mínima de 18 anos.";r.contains("invalid_cpf",true)->"CPF inválido.";r.contains("invalid_credentials",true)||r.contains("Invalid login",true)->"E-mail ou senha incorretos.";r.contains("Email address not authorized",true)->"O SMTP ainda não está configurado para clientes externos.";r.contains("otp_send_failed",true)->"Não foi possível enviar o código. Verifique o SMTP do Supabase.";else->r.replace("_"," ")}}
